#!/usr/bin/env python3
"""drug/ligand_prep — auto-generated run.py (archetype=drug).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "drug"
BRAIN = "drug"
SKILL = "ligand_prep"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'ligand_prep', 'n_compounds': 0, 'best_score': 0.0, 'compound_csv': '', 'diagnostics': {'brain': 'drug', 'archetype': 'drug'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """RDKit + OpenBabel ligand prep:tautomer enumerate + protonation + 3D embed + SDF write。
    输入:smiles / sdf_in / out_sdf / pH (7.4)
    输出:n_variants / out_sdf / tautomers
    """
    import os as _os
    import tempfile as _tempfile
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    smiles = payload.get("smiles")
    sdf_in = payload.get("sdf_in")
    out_sdf = payload.get("out_sdf") or _tempfile.NamedTemporaryFile(suffix=".sdf", delete=False).name
    pH = float(payload.get("pH", 7.4))
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "out_sdf": out_sdf, "pH": pH}

    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_variants": 1, "out_sdf": out_sdf,
                "tautomers": [], "diagnostics": {**diagnostics, "dry": True}}
    if not smiles and not sdf_in:
        return {"ok": False, "error": "需要 smiles 或 sdf_in", "diagnostics": diagnostics}

    script = (
        "import json, sys\n"
        "from rdkit import Chem\n"
        "from rdkit.Chem import AllChem\n"
        "from rdkit.Chem.MolStandardize import rdMolStandardize\n"
        f"smi = {smiles!r}; sdf_in = {sdf_in!r}; out_sdf = {out_sdf!r}\n"
        "if sdf_in: mol = Chem.SDMolSupplier(sdf_in, removeHs=False)[0]\n"
        "else: mol = Chem.MolFromSmiles(smi)\n"
        "if mol is None: print(json.dumps({'__err':'parse_fail'})); sys.exit(1)\n"
        "te = rdMolStandardize.TautomerEnumerator()\n"
        "tauts = list(te.Enumerate(mol))\n"
        "writer = Chem.SDWriter(out_sdf)\n"
        "for t in tauts:\n"
        "    t = Chem.AddHs(t)\n"
        "    AllChem.EmbedMolecule(t, randomSeed=42)\n"
        "    try: AllChem.MMFFOptimizeMolecule(t)\n"
        "    except Exception: pass\n"
        "    writer.write(t)\n"
        "writer.close()\n"
        "json.dump({'n_variants': len(tauts), 'out_sdf': out_sdf,\n"
        "           'tautomers': [Chem.MolToSmiles(Chem.RemoveHs(t)) for t in tauts]}, sys.stdout)\n"
    )
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 120)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "ligand_prep 失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, **parsed, "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
